import{_ as e,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"NotEnoughAccuracy","description":"","frontmatter":{"title":"NotEnoughAccuracy","order":9},"headers":[],"relativePath":"zh/mods/not-enough-accuracy.md","filePath":"zh/mods/not-enough-accuracy.md","lastUpdated":1786943111000}'),n={name:"zh/mods/not-enough-accuracy.md"};function c(s,a,l,i,h,u){return o(),t("div",null,[...a[0]||(a[0]=[r(`<h1 id="notenoughaccuracy" tabindex="-1">NotEnoughAccuracy <a class="header-anchor" href="#notenoughaccuracy" aria-label="Permalink to &quot;NotEnoughAccuracy&quot;">​</a></h1><blockquote><p>觉得 XPerfect 还不够严格？<strong>Not Enough Accuracy（NEAcc / NEA）</strong> 把每一毫秒都纳入计算，给出最精确的游玩精度。</p><p>项目地址：<a href="https://github.com/adofaiex/NotEnoughAccuracy" target="_blank" rel="noreferrer">https://github.com/adofaiex/NotEnoughAccuracy</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>本 Mod 不影响 ADOFAI 的判定！</strong> 它只是另一种计算精度的方式。</p></div><h2 id="精度算法" tabindex="-1">精度算法 <a class="header-anchor" href="#精度算法" aria-label="Permalink to &quot;精度算法&quot;">​</a></h2><h3 id="tiles-总块数" tabindex="-1">Tiles（总块数） <a class="header-anchor" href="#tiles-总块数" aria-label="Permalink to &quot;Tiles（总块数）&quot;">​</a></h3><p>总块数 = VE + EP + PP + LP + VL + FailMiss − 中旋（Midspin），每个中旋只算一块。</p><h3 id="每块得分" tabindex="-1">每块得分 <a class="header-anchor" href="#每块得分" aria-label="Permalink to &quot;每块得分&quot;">​</a></h3><p>只考虑能把你「向前推进」的判定：</p><ul><li>未开启 no fail 时<strong>漏块</strong>：<code>-100</code></li><li>其余情况：<code>max(100 − |x|, 0)</code>，其中 <code>x</code> 是该块相对精确时机的<strong>毫秒偏差</strong>（与实际判定无关）</li></ul><p>即：每块基础分 100 分，每偏差 1 毫秒扣 1 分，最多扣到 0 分；no fail 模式下漏块记 -100。</p><h3 id="额外扣分" tabindex="-1">额外扣分 <a class="header-anchor" href="#额外扣分" aria-label="Permalink to &quot;额外扣分&quot;">​</a></h3><ul><li>每个 TooEarly / TooLate 额外扣 <strong>50</strong></li><li>每个 FailOverload 额外扣 <strong>100</strong></li></ul><h3 id="总精度" tabindex="-1">总精度 <a class="header-anchor" href="#总精度" aria-label="Permalink to &quot;总精度&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TotalScores = 上述所有得分之和（可为负）</span></span>
<span class="line"><span>NEAccuracy% = TotalScores / Tiles</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="许可" tabindex="-1">许可 <a class="header-anchor" href="#许可" aria-label="Permalink to &quot;许可&quot;">​</a></h2><p>GPL v3</p>`,16)])])}const g=e(n,[["render",c]]);export{p as __pageData,g as default};
